static mt_u32 check_untest_regs(ulong reg_addr)
{
	mt_u32 ret = 0; // 0:normal, 1:untest write 0xff or 0x00 2: untest all(read default value, write 0xff&&0x00)
	mt_u32 reg_tmp = (mt_u32)(reg_addr & 0xffffUL);

	reg_tmp += 0x3000;  //To match Cypress register manual
	if ((reg_tmp >= 0x3c30UL && reg_tmp <= 0x3c3fUL) ||
			(reg_tmp >= 0x3c80UL && reg_tmp <= 0x3c86UL) ||
			(reg_tmp >= 0x3c90UL && reg_tmp <= 0x3c9fUL) ||
			(reg_tmp >= 0x3ca0UL && reg_tmp <= 0x3ca6UL) ||
			(reg_tmp >= 0x3cb0UL && reg_tmp <= 0x3cbfUL) ||
			(reg_tmp >= 0x3e00UL && reg_tmp <= 0x3e5eUL) ||
			(reg_tmp >= 0x37b0UL && reg_tmp <= 0x37ffUL) ||
			(reg_tmp >= 0x3e4cUL && reg_tmp <= 0x3e57UL) ||
			(reg_tmp >= 0x3c68UL && reg_tmp <= 0x3c6aUL) ||
			reg_tmp == 0x30f4UL ||
			reg_tmp == 0x30d2UL) {
		ret = 2;
	} else if (reg_tmp == 0x382dUL || reg_tmp == 0x303fUL ||
			   reg_tmp == 0x30d1UL || reg_tmp == 0x361aUL ||
			   (reg_tmp >= 0x382fUL && reg_tmp <= 0x3833UL) ||
			   reg_tmp == 0x3facUL) {
		ret = 1;
	} else if (reg_tmp == 0x3031UL || reg_tmp == 0x3090UL || reg_tmp == 0x3630UL ||
			   reg_tmp == 0x363bUL || reg_tmp == 0x380dUL || reg_tmp == 0x308fUL ||
			   (reg_tmp >= 0x3040UL && reg_tmp <= 0x3044UL) ||
			   (reg_tmp >= 0x362bUL && reg_tmp <= 0x362fUL) ||
			   reg_tmp == 0x38cfUL || (reg_tmp >= 0x304dUL && reg_tmp <= 0x3051UL) ||
			   (reg_tmp >= 0x3636UL && reg_tmp <= 0x363aUL) || reg_tmp == 0x30ecUL ||
			   reg_tmp == 0x3b81UL || (reg_tmp >= 0x3b88UL && reg_tmp <= 0x3ba9UL) ||
			   (reg_tmp >= 0x3bb4UL && reg_tmp <= 0x3bb6UL) ||
			   reg_tmp == 0x3009UL || reg_tmp == 0x302cUL || reg_tmp == 0x307fUL ||
			   reg_tmp == 0x308eUL) {
		//Reference redmine8550 comments 2
		//special regs , do NOT test default values
		ret = 3;
	}
	return ret;
}

