static mt_u32 is_special_reg_rw8(ulong reg_addr, ulong ip_base, mt_u8 read, mt_u8 *val)
{
	ulong reg_addr_tmp;
	mt_u8 reg_val;
	mt_u8 reg_val_tmp;
	mt_u32 ret = 0;
	mt_u32 ret_tmp;

	if ((reg_addr & 0x0fff0000) == (HDMI20_REG_BASE_ADDR & 0x0fff0000)) {
		reg_addr_tmp = reg_addr & 0xffff;
		reg_addr_tmp -= ip_base;
		if ( reg_addr_tmp >= 0x00d8 &&  reg_addr_tmp <= 0x00eb) {
			//redmine8550 comment2
			reg_val = misc_reg_read8_single(REG_ADDR__DDC_MANUAL);
			reg_val_tmp = reg_val;
			reg_val &= (~(1 << 6));
			reg_val |= (1 << 6);
			ret_tmp = misc_reg_write8_single(REG_ADDR__DDC_MANUAL, reg_val);
			if (read) {
				(*val) = misc_reg_read8_single(reg_addr);
				ret_tmp = misc_reg_write8_single(REG_ADDR__DDC_MANUAL, reg_val_tmp);
			} else {
				ret_tmp = misc_reg_write8_single(reg_addr, *val);
				ret_tmp = misc_reg_write8_single(REG_ADDR__DDC_MANUAL, reg_val_tmp);
			}
			if ( ret_tmp == BB_SUCCESS ) {
				ret = 1;
			} else {
				ret = 0;
			}
		}
	}
	return ret;
}

