#define HDMI20_TEST_REG_MAX_LEN (0x1000)
static mt_u32 verify_reg_default_val(REG_TEST_T *array, mt_u32 len, ulong reg_base)
{
	mt_u32 ret = 0;
	mt_u32 i;
	mt_u8 reg_default[HDMI20_TEST_REG_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xff;
	mt_u8 uncomp[HDMI20_TEST_REG_MAX_LEN];

	memset(reg_default, 0, sizeof(reg_default));
	memset(uncomp, 1, sizeof(uncomp));
	//reset module here

	//read default
	//Do not embed the key ram, otherwise 0x304d~0x3051, 0x3636~0x363a is the embedded value.
	//The default values of bit3 and bit4 of 0x308f are not fixed, which are related to the reading time, and may also be 0.
	//The default values of bit7 and bit0 of 0x30f8 are not fixed, which is related to the reading time.
	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (offset == 0xf4 || offset == 0xd2 || offset == 0x642 || offset == 0xf8f || offset == 0xf90) {
			printf("0x%lx:   ----fifo reg, NOT dump \n", (ulong)(reg_base + offset));
		} else if (hdmi20_reg_invalid(reg_base + offset)) {
			//printf("0x%x:	Invalid Register\n",reg_base + offset);
		} else if (2 == check_untest_regs(reg_base + offset)) {
			//printf("0x%x:	Untest Registers\n",reg_base + offset);
		} else if (0xff == array[i].mask) {
			//printf("0x%x:	Reserved OR N/A Register\n",reg_base + offset);
		} else if (0xff == array[i].maskw) {
			//printf("0x%x:	Write Only Register\n",reg_base + offset);
		} else {
			if (0 == is_special_reg_rw8(reg_base + offset, 0UL, 1, &(reg_default[i]))) {
				reg_default[i] = misc_reg_read8_single(reg_base + offset);
			}
			if (3 != check_untest_regs(reg_base + offset)) {
				uncomp[i] = 0;
			}
		}
	}

	if (0) {
		SSHH_PRINTF("Read HDMI20 default value:\n");
		for (i = 0; i < len; i++) {
			SSHH_PRINTF("{0x%4x, 0x%02x, 0x%02x, 0x%02x, 0x%02x},\n", 0x3000 + i, reg_default[i], 0x00, 0x03, 8);
		}
		SSHH_PRINTF("\n");
	}

	for (i = 0; i < len; i++) {
		if (reg_default[i] != array[i].reg_default_value && 0 == uncomp[i]) {
			mask = array[i].maskr;
			if (array[i].reg_addr == 0x308f) {
				mask |= 0x18;
			} else if (array[i].reg_addr == 0x30f8) {
				mask |= 0x81;
			}

			if ( (reg_default[i] & (0xff - mask)) != (array[i].reg_default_value & (0xff - mask)) ) {
				ret ++;
				SSHH_PRINTF("Default Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", array[i].reg_addr, array[i].reg_default_value, reg_default[i], mask, ret);
			}
		}
	}

	if (ret == 0) {
		SSHH_PRINTF("Default Value ALL match!!!! tested HDMI page 0 default value OK\n");
	}

	return ret;
}

#define HDMI20_TEST_REG1XXX_MAX_LEN (0x100)
static mt_u32 verify_reg1xxx_default_val(REG_TEST_T *array, mt_u32 len, ulong reg_base)
{
	mt_u32 ret = 0;
	mt_u32 i;
	mt_u32 reg_default[HDMI20_TEST_REG1XXX_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xffffffff;
	mt_u32 uncomp[HDMI20_TEST_REG1XXX_MAX_LEN];

	memset(reg_default, 0, sizeof(reg_default));
	memset(uncomp, 0, sizeof(uncomp));
	//reset module here

	//read default
	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		reg_default[i] = misc_reg_read32_single(reg_base + offset);
	}

	if ( 0 ) {
		SSHH_PRINTF("Read HDMI20 default value:\n");
		for (i = 0; i < len; i++) {
			SSHH_PRINTF("{0x%04x, 0x%08x},\n", 0x4000 + (i << 2), reg_default[i]);
		}
		SSHH_PRINTF("\n");
	}

	for (i = 0; i < len; i++) {
		if (reg_default[i] != array[i].reg_default_value && 0 == uncomp[i] && (array[i].attr & 0x1)) {
			mask = array[i].maskr;
			if (array[i].reg_addr == 0x4034 || array[i].reg_addr == 0x400c) {
				//Via redmine 8550 comment9 and comment10
				mask = 0xffffffff;
			}
			if ( (reg_default[i] & (0xffffffff - mask)) != (array[i].reg_default_value & (0xffffffff - mask)) ) {
				ret ++;
				SSHH_PRINTF("Default Value DON'T match: reg[0x%x], 0x%08x(Golden) != 0x%08x(Read), mask=0x%08x,0x%08x, err cnt=%04d\n", array[i].reg_addr, array[i].reg_default_value, reg_default[i], mask, 0xffffffff - mask, ret);
			}
		}
	}

	if (ret == 0) {
		SSHH_PRINTF("Default Value ALL match!!!! tested HDMI page 1 default value OK\n");
	}

	return ret;
}

#define HDMI20_TEST_REG2XXX_MAX_LEN (0x1000)
static mt_u32 verify_reg2xxx_default_val(REG_TEST_T *array, mt_u32 len, ulong reg_base)
{
	mt_u32 ret = 0;
	mt_u32 i, j;
	mt_u32 reg_default[HDMI20_TEST_REG2XXX_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xffffffff;
	mt_u32 uncomp[HDMI20_TEST_REG2XXX_MAX_LEN];

	memset(reg_default, 0, sizeof(reg_default));
	memset(uncomp, 0, sizeof(uncomp));
	//reset module here

	//read default
	for (j = 0; j < 2; j++) {
		for (i = 0; i < len; i++) {
			offset = array[j].reg_addr - 0x3000 + (i << 2);
			SSHH_PRINTF("RegBase=0x%lx. offset=0x%lx\n", reg_base, offset);
			reg_default[((array[j].reg_addr - 0x5000) >> 2) + i] = misc_reg_read32_single(reg_base + offset);
		}
	}

	{
		SSHH_PRINTF("Read HDMI20 default value:\n");
		for (i = 0; i < len * 2; i++) {
			SSHH_PRINTF("{0x%04x, 0x%08x},\n", 0x5000 + (i << 2), reg_default[i]);
		}
		SSHH_PRINTF("\n");
	}

	for (j = 0; j < 2; j++) {
		for (i = 0; i < len; i++) {
			if (reg_default[i] != array[j].reg_default_value && 0 == uncomp[i] && (array[i].attr & 0x1)) {
				mask = array[i].maskr;
				if ( (reg_default[i] & (0xffffffff - mask)) != (array[i].reg_default_value & (0xffffffff - mask)) ) {
					ret ++;
					SSHH_PRINTF("Default Value DON'T match: reg[0x%x], 0x%08x(Golden) != 0x%08x(Read), mask=0x%08x,0x%08x, err cnt=%04d\n", array[i].reg_addr, array[i].reg_default_value, reg_default[i], mask, 0xffffffff - mask, ret);
				}
			}
		}
	}

	if (ret == 0) {
		SSHH_PRINTF("Default Value ALL match!!!! tested HDMI page 2 default value OK\n");
	}

	return ret;
}

static mt_u32 is_untest_rw_reg(ulong reg_base, ulong offset, mt_u32 attr, mt_u32 mask, mt_u8 print)
{
	mt_u32 ret = 0;

	if (offset == 0xf4 || offset == 0xd2 || offset == 0x642 || offset == 0xf8f || offset == 0xf90) {
		printf("0x%lx:	----fifo reg, NOT dump \n", (ulong)(reg_base + offset));
		ret = 1;
	} else if (hdmi20_reg_invalid(reg_base + offset)) {
		//printf("0x%x:	Invalid Register\n",reg_base+offset);
		ret = 2;
	} else if (2 == check_untest_regs(reg_base + offset)) {
		//printf("0x%x:	Untest Registers\n",reg_base + offset);
		ret = 3;
	} else if (0xff == mask) {
		//printf("0x%x:	Reserved OR N/A Register\n",reg_base + offset);
		ret = 4;
	} else if (is_need_timing(reg_base + offset)) {
		//printf("0x%x:	Need Timing\n",reg_base + offset);
		ret = 5;
	} else if (is_need_special_conditions(reg_base + offset)) {
		//printf("0x%x:	Need Special Conditions\n",reg_base + offset);
		ret = 6;
	} else if ( 0x3 != ( attr & 0x3)) {
		//printf("0x%x:	Read or Write Only Register\n",reg_base + offset);
		ret = 7;
	}

	return ret;
}

