static mt_u32 verify_reg_wr_val(REG_TEST_T *array, mt_u32 len, ulong reg_base, mt_u32 val)
{
	mt_u32 ret = 0;
	mt_u32 ret_tmp = 0;
	mt_u32 i, kk;
	mt_u8 reg_ff[HDMI20_TEST_REG_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xff;
	mt_u8 uncomp[HDMI20_TEST_REG_MAX_LEN];
	mt_u32 len_tmp;
	mt_u32 w1t = 0;

	if (len > HDMI20_TEST_REG_MAX_LEN) {
		SSHH_PRINTF("Array is too large: %d. It shall be <= %d\n", len, HDMI20_TEST_REG_MAX_LEN);
		return 1;
	}
	memset(reg_ff, 0, sizeof(reg_ff));
	memset(uncomp, 1, sizeof(uncomp));

	//write 0xff/0x00  0x3000 ~ 0x3aff, w8 -> r8 -> compare8
	SSHH_PRINTF("Start to Write HDMI20 register to 0x%x, len=%d:\n", val, len);
	if ( len < 0xb00) {
		len_tmp = len;
	} else {
		len_tmp = 0xb00;
	}
	for (i = 0; i < len_tmp; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == is_untest_rw_reg(reg_base, offset, array[i].attr, array[i].mask, 1)) {
			printf("write 0x%lx: 0x%x\n", (ulong)(reg_base + offset), val);
			if (0 == check_untest_regs(reg_base + offset)) {
				/* Write, Read is inconsistent */
				/* ret = 1, write but not check the read back value */
				uncomp[i] = 0;
			}
			ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)val);
			if (offset == 0xa04) {
				printf("after write 0x%lx: 0x%x\n", (ulong)(reg_base + offset), val);
				IC_TEST_DEBUG(IC_TEST_DBG_ENABLE);
			}
		}

		if (0 == is_untest_rw_reg(reg_base, offset, array[i].attr, array[i].mask, 0)) {
			reg_ff[i] = misc_reg_read8_single(reg_base + offset);
			ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)array[i].reg_default_value);
		}

		if (0 == uncomp[i]) {
			if (is_intr_status(reg_base + offset)) {
				for (kk = 0; kk < (sizeof(g_hdmi20_reg0xxx_wclear_flag) / sizeof(g_hdmi20_reg0xxx_wclear_flag[0])); kk++) {
					if (array[i].reg_addr == g_hdmi20_reg0xxx_wclear_flag[kk].reg_addr) {
						if ( val && (reg_ff[i] & g_hdmi20_reg0xxx_wclear_flag[kk].mask1) != 0 ) {
							ret_tmp = misc_reg_write8_single(reg_base + (array[i].reg_addr - 0x3000), (mt_u8)val);
							reg_ff[i] = misc_reg_read8_single(reg_base + (array[i].reg_addr - 0x3000));
							if ( val && (reg_ff[i] & g_hdmi20_reg0xxx_wclear_flag[kk].mask1) != 0 ) {
								ret ++;
								SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)0, reg_ff[i], g_hdmi20_reg0xxx_wclear_flag[kk].mask1, ret);
							}
						} else if (0 == val && (reg_ff[i] & (g_hdmi20_reg0xxx_wclear_flag[kk].mask0)) != 0 ) {
							ret ++;
							SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)0, reg_ff[i], g_hdmi20_reg0xxx_wclear_flag[kk].mask0, ret);
						}
						break;
					}
				}
			} else if (is_read_always_zero((ulong)offset)) {
				if ( reg_ff[i] != 0) {
					ret ++;
					SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)0, reg_ff[i], mask, ret);
				}
			} else {
				w1t = is_w1t_regs((ulong)offset);
				mask = array[i].mask | array[i].maskw | array[i].maskr;
				if ( w1t == 0xffffffff) {
					if ( (reg_ff[i] & ((mt_u8)0xff - (mt_u8)mask)) != ((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask)) ) {
						ret ++;
						SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask)), reg_ff[i], mask, ret);
					}
				} else {
					mt_u8 mw1t = g_hdmi20_reg0xxx_w1t_flag[w1t].mask0;
					mt_u8 chk = 0;
					if ( (reg_ff[i] & ((mt_u8)0xff - (mt_u8)mask) & (~mw1t)) != ((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask) & (~mw1t)) ) {
						chk |= 0x1;
						ret ++;
						SSHH_PRINTF("Writea 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask) & (~mw1t)), (mt_u32)reg_ff[i], (mt_u32)(mask & (~mw1t)), ret);
					}
					if ( val & mw1t ) {
						mt_u8 rega0 = 0;
						mt_u8 rega1 = 0;
						mt_u8 rega2 = 0;
						rega0 = misc_reg_read8_single(reg_base + offset);
						ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)mw1t);
						rega1 = misc_reg_read8_single(reg_base + offset);
						ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)mw1t);
						rega2 = misc_reg_read8_single(reg_base + offset);
						if ((( (~rega0) & mw1t) != ( rega1 & mw1t)) || \
								(( rega0 & mw1t) != ( rega2 & mw1t))) {
							chk |= 0x2;
							if (( chk & 0x1) == 0) {
								ret ++;
							}
							SSHH_PRINTF("Writeb w1t 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", \
										val, array[i].reg_addr, (mt_u32)((~rega0)&mw1t), (mt_u32)(rega1 & mw1t), (mt_u32)(rega0 & mw1t), (mt_u32)(rega2 & mw1t), (mt_u32)mw1t, ret);
						}
					}
				}
			}
		}

		for (kk = 0; kk < (sizeof(g_hdmi20_reg0xxx_reset_flag) / sizeof(g_hdmi20_reg0xxx_reset_flag[0])); kk++) {
			if (array[i].reg_addr == g_hdmi20_reg0xxx_reset_flag[kk].reg_addr) {
				ret_tmp = misc_reg_put8(g_hdmi20_reg0xxx_reset_flag[kk].reg_addr, g_hdmi20_reg0xxx_reset_flag[kk].mask, 0x00);
				break;
			}
		}

	}

	//write 0xff/0x00  0x3b00 ~ 0x3fff, write all -> read all -> compare all
	if ( val ) {
		//make sure the write / read in the same bank
		ret_tmp = misc_reg_write8_single(reg_base + 0xb7f, (mt_u8)0);
		ret_tmp = misc_reg_write8_single(reg_base + 0xc27, (mt_u8)0);
	} else {
		//make sure the write / read in the same bank
		ret_tmp = misc_reg_write8_single(reg_base + 0xb7f, (mt_u8)0xff);
		ret_tmp = misc_reg_write8_single(reg_base + 0xc27, (mt_u8)0xff);
	}
	ret_tmp = (mt_u32)misc_reg_read8_single(HDMI20_REG_BASE_ADDR + 0xb7f);
	printf("reg[0x3b7f] = 0x%x\n", ret_tmp);
	ret_tmp = (mt_u32)misc_reg_read8_single(HDMI20_REG_BASE_ADDR + 0xc27);
	printf("reg[0x3c27] = 0x%x\n", ret_tmp);
	for (i = 0xb00; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == is_untest_rw_reg(reg_base, offset, array[i].attr, array[i].mask, 1)) {
			printf("write 0x%lx: 0x%x\n", (ulong)(reg_base + offset), val);
			if (0 == check_untest_regs(reg_base + offset)) {
				/* Write, Read is inconsistent */
				/* ret = 1, write but not check the read back value */
				uncomp[i] = 0;
			}
			ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)val);
			if ( 0xb0c == offset ) {
				reg_ff[i] = misc_reg_read8_single(reg_base + offset);
				ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)0);
			}
		}
	}

	IC_TEST_DEBUG(IC_TEST_DBG_ENABLE);

	for (i = 0xb00; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == is_untest_rw_reg(reg_base, offset, array[i].attr, array[i].mask, 0)) {
			if ( 0xb0c != offset ) {
				//already read immediately after write
				reg_ff[i] = misc_reg_read8_single(reg_base + offset);
			}
		}
	}

	for (i = 0xb00; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == uncomp[i]) {
			if (is_intr_status(reg_base + offset)) {
				for (kk = 0; kk < (sizeof(g_hdmi20_reg0xxx_wclear_flag) / sizeof(g_hdmi20_reg0xxx_wclear_flag[0])); kk++) {
					if (array[i].reg_addr == g_hdmi20_reg0xxx_wclear_flag[kk].reg_addr) {
						if ( val && (reg_ff[i] & g_hdmi20_reg0xxx_wclear_flag[kk].mask1) != 0 ) {
							ret ++;
							SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)0, reg_ff[i], g_hdmi20_reg0xxx_wclear_flag[kk].mask1, ret);
						} else if (0 == val && (reg_ff[i] & (g_hdmi20_reg0xxx_wclear_flag[kk].mask0)) != 0 ) {
							ret ++;
							SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)0, reg_ff[i], g_hdmi20_reg0xxx_wclear_flag[kk].mask0, ret);
						}
						break;
					}
				}
			} else if (is_read_always_zero((ulong)offset)) {
				if ( reg_ff[i] != 0) {
					ret ++;
					SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)0, reg_ff[i], mask, ret);
				}
			} else if ( 0xb7e == offset ) {
				// VTG is deleted in sym6, don't care
				;
			} else {
				mask = array[i].mask | array[i].maskw | array[i].maskr;
				if (0x3fac == offset) {
					mask |= 0x40;
				}
				if ( (reg_ff[i] & ((mt_u8)0xff - (mt_u8)mask)) != ((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask)) ) {
					ret ++;
					SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask)), reg_ff[i], mask, ret);
				} else if (0x3fac == offset) {
					mt_u8  reg_tt0 = 0;
					mt_u8  reg_ttw = 0;
					mt_u8  reg_tt1 = 0;
					reg_tt0 = misc_reg_read8_single(reg_base + offset);
					reg_tt0 &= 0x40;
					reg_tt0 >>= 6;
					reg_ttw = (mt_u8)val;
					reg_ttw &= 0x40;
					reg_ttw >>= 6;
					ret_tmp = misc_reg_write8_single(reg_base + offset, (mt_u8)val);
					reg_tt1 = misc_reg_read8_single(reg_base + offset);
					reg_tt1 &= 0x40;
					reg_tt1 >>= 6;
					if (reg_tt1 != (reg_ttw != reg_tt0)) {
						ret ++;
						SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, (mt_u32)((mt_u8)val & ((mt_u8)0xff - (mt_u8)mask)), reg_ff[i], mask, ret);
					}
				}
			}
		}
	}

	if ( 0 ) {
		SSHH_PRINTF("Print Read HDMI20 value after writing 0x%x:\n", val);
		for (i = 0; i < len; i++) {
			SSHH_PRINTF("{0x%4x, 0x%02x, 0x%02x, 0x%02x, 0x%02x},\n", 0x3000 + i, reg_ff[i], 0x00, 0x03, 8);
		}
		SSHH_PRINTF("\n");
	}

	if (ret == 0) {
		SSHH_PRINTF("Tested HDMI page 0 write 0x%x OK\n", val);
	}
	IC_TEST_DEBUG(IC_TEST_DBG_ENABLE);
	return ret;
}

static mt_u32 verify_reg_wr_val_hangup_check(REG_TEST_T *array, mt_u32 len, ulong reg_base, mt_u32 val)
{
	mt_u32 ret = 0;
	mt_u32 i;
	mt_u8 reg_ff[HDMI20_TEST_REG_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xff;
	mt_u8 uncomp[HDMI20_TEST_REG_MAX_LEN];

	if (len > HDMI20_TEST_REG_MAX_LEN) {
		SSHH_PRINTF("Array is too large: %d. It shall be <= %d\n", len, HDMI20_TEST_REG_MAX_LEN);
		return 1;
	}
	memset(reg_ff, 0, sizeof(reg_ff));
	memset(uncomp, 1, sizeof(uncomp));

	//write 0xff/0x00
	SSHH_PRINTF("Start to Write HDMI20 register to 0x%x, len=%d:\n", val, len);
	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == is_untest_rw_reg(reg_base, offset, array[i].attr, array[i].mask, 1)) {
			printf("write 0x%lx: 0xff\n", (ulong)(reg_base + offset));
			if (0 == check_untest_regs(reg_base + offset)) {
				/* Write, Read is inconsistent */
				/* ret = 1, write but not check the read back value */
				uncomp[i] = 0;
			}
			ret = misc_reg_write8_single(reg_base + offset, 0xff);
		}
	}
	SSHH_PRINTF("Read HDMI20 value after writing 0x%x:\n", val);
	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == is_untest_rw_reg(reg_base, offset, array[i].attr, array[i].mask, 0)) {
			reg_ff[i] = misc_reg_read8_single(reg_base + offset);
		}
	}

	if ( 0 ) {
		SSHH_PRINTF("Print Read HDMI20 value after writing 0x%x:\n", val);
		for (i = 0; i < len; i++) {
			SSHH_PRINTF("{0x%4x, 0x%02x, 0x%02x, 0x%02x, 0x%02x},\n", 0x3000 + i, reg_ff[i], 0x00, 0x03, 8);
		}
		SSHH_PRINTF("\n");
	}

	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == uncomp[i]) {
			mask = array[i].mask;
			if ( (reg_ff[i] & (0xff - mask)) != (val & (0xff - mask)) ) {
				ret ++;
				SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%02x(Golden) != 0x%02x(Read), mask=0x%02x, err cnt=%04d\n", val, array[i].reg_addr, array[i].reg_default_value, reg_ff[i], mask, ret);
			}
		}
	}

	if (ret == 0) {
		SSHH_PRINTF("Default Value ALL match!!!! tested HDMI page 0 write 0x%x OK\n", val);
	}
	SSHH_PRINTF("Write all the 0x%x value OK, NOT HANGUP!!!\n", val);
	return ret;
}

static mt_u32 verify_reg1xxx_wr_val(REG_TEST_T *array, mt_u32 len, ulong reg_base, mt_u32 val)
{
	mt_u32 ret = 0;
	mt_u32 ret_tmp = 0;
	mt_u32 i;
	mt_u32 reg_ff[HDMI20_TEST_REG1XXX_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xffffffff;
	mt_u32 uncomp[HDMI20_TEST_REG1XXX_MAX_LEN];

	if (len > HDMI20_TEST_REG1XXX_MAX_LEN) {
		SSHH_PRINTF("Array is too large: %d. It shall be <= %d\n", len, HDMI20_TEST_REG_MAX_LEN);
		return 1;
	}
	memset(reg_ff, 0, sizeof(reg_ff));
	memset(uncomp, 0, sizeof(uncomp));

	//write 0xff/0x00
	SSHH_PRINTF("Start to Write HDMI20 register to 0x%x, len=%d:\n", val, len);
	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		//write 0xff/0x00
		ret_tmp |= misc_reg_write32_single(reg_base + offset, val);
		//read back
		reg_ff[i] = misc_reg_read32_single(reg_base + offset);
		//compare
		if (0 == uncomp[i] && ((array[i].attr & 0x3) == 0x3)) { //r/w registers
			mask = array[i].mask | array[i].maskw | array[i].maskr;
			if ( (reg_ff[i] & (0xffffffff - mask)) != (val & (0xffffffff - mask)) ) {
				ret ++;
				SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%08x(Golden) != 0x%08x(Read), mask=0x%08x, err cnt=%04d\n", val, array[i].reg_addr, array[i].reg_default_value, reg_ff[i], mask, ret);
			}
		}
	}

	if ( 0 ) {
		SSHH_PRINTF("Print Read HDMI20 value after writing 0x%x:\n", val);
		for (i = 0; i < len; i++) {
			SSHH_PRINTF("{0x%4x, 0x%08x},\n", 0x4000 + (i << 2), reg_ff[i]);
		}
		SSHH_PRINTF("\n");
	}

	if (ret == 0 && ret_tmp == 0) {
		SSHH_PRINTF("Tested HDMI page 1 write 0x%x OK\n", val);
	}
	return ret;
}

static mt_u32 verify_reg2xxx_wr_val(REG_TEST_T *array, mt_u32 len, ulong reg_base, mt_u32 val)
{
	mt_u32 ret = 0;
	mt_u32 ret_tmp = 0;
	mt_u32 i, j;
	mt_u32 reg_ff[HDMI20_TEST_REG2XXX_MAX_LEN];
	ulong offset;
	mt_u32 mask = 0xffffffff;
	mt_u32 uncomp[HDMI20_TEST_REG2XXX_MAX_LEN];

	if (len > HDMI20_TEST_REG2XXX_MAX_LEN) {
		SSHH_PRINTF("Array is too large: %d. It shall be <= %d\n", len, HDMI20_TEST_REG_MAX_LEN);
		return 1;
	}
	memset(reg_ff, 0, sizeof(reg_ff));
	memset(uncomp, 0, sizeof(uncomp));

	//write 0xff/0x00
	SSHH_PRINTF("Start to Write HDMI20 register to 0x%x, len=%d:\n", val, len);
	for (j = 0; j < 2; j++) {
		for (i = 0; i < len; i++) {
			offset = array[0].reg_addr - 0x3000 + (i << 2);
			ret_tmp = misc_reg_write32_single(reg_base + offset, val);
		}
	}
	SSHH_PRINTF("Read HDMI20 value after writing 0x%x:\n", val);
	for (j = 0; j < 2; j++) {
		for (i = 0; i < len; i++) {
			offset = array[j].reg_addr - 0x3000 + (i << 2);
			reg_ff[i] = misc_reg_read32_single(reg_base + offset);
		}
	}

	{
		SSHH_PRINTF("Print Read HDMI20 value after writing 0x%x:\n", val);
		for (i = 0; i < len * 2; i++) {
			SSHH_PRINTF("{0x%4x, 0x%08x},\n", 0x5000 + (i << 2), reg_ff[i]);
		}
		SSHH_PRINTF("\n");
	}

	for (i = 0; i < len; i++) {
		offset = array[i].reg_addr - 0x3000;
		if (0 == uncomp[i] && ((array[i].attr & 0x3) == 0x3)) { //r/w registers
			mask = array[i].mask | array[i].maskw | array[i].maskr;
			if ( (reg_ff[i] & (0xffffffff - mask)) != (val & (0xffffffff - mask)) ) {
				ret ++;
				SSHH_PRINTF("Write 0x%x Value DON'T match: reg[0x%x], 0x%08x(Golden) != 0x%08x(Read), mask=0x%08x, err cnt=%04d\n", val, array[i].reg_addr, array[i].reg_default_value, reg_ff[i], mask, ret);
			}
		}
	}

	if (ret == 0 && ret_tmp == 0) {
		SSHH_PRINTF("Default Value ALL match!!!! tested HDMI page 2 write 0x%x OK\n", val);
	}
	return ret;
}

mt_u32 do_case_reg_rw(void)
{
	#if defined(CONFIG_MT_CHIP_ETUDE2)
	//0x3000 group
	int i = 0;
	int size = 0;
	mt_u8 reg_val = 0;
	mt_u8 comp_val = 0;
	int j = 0;
	mt_u32 ret = BB_SUCCESS;
	mt_u32 reg_addr = 0;
	REG_TEST_T *array;
	mt_u32 array_width;

	array = g_hdmi_reg_rw_test;
	array_width = sizeof(array) / (sizeof(array[0]));

	hdmi_block_reset_cmd();   //reset first
	size = array_width;//sizeof(array) / sizeof(array[0]);
	for (i = 0; i < size; i++) {
		comp_val = (mt_u8)array[i].reg_default_value;
		if (array[i].reg_addr >= 0x3000 && array[i].reg_addr < 0x4000) {
			reg_addr = array[i].reg_addr;
			reg_addr += HDMI20_REG_BASE_ADDR;
			reg_addr -= 0x3000;
		}
		if (array[i].attr & 0x3) {
			//read only
			for (j = 0; j < 2; j++) {
				if (j == 1) {
					reg_val = 0xff;
					if (array[i].attr & 0x2) {
						comp_val = reg_val;
					} else if (array[i].attr == 0x1) {
						comp_val = (mt_u8)array[i].reg_default_value;
					}
					misc_reg_write8(reg_addr, &reg_val, 1);
				}
				misc_reg_read8(reg_addr, &reg_val, 1);
				if ( reg_val != comp_val) {
					SSHH_PRINTF("\n%s_%d: read only fail: j=%d(0: check default, 1:check write) reg0x%x, r:x%x default:0x%x, mask:0x%x, attr:%d, w:%d\n", __func__, __LINE__, \
								j, reg_addr, \
								(mt_u32)reg_val, array[i].reg_default_value, array[i].mask, array[i].attr, \
								array[i].width);
					ret = BB_FAILURE;
				}
			}
		}
	}
	#else
	mt_u32 ret = BB_SUCCESS;
	mt_u32 ret_tmp = BB_SUCCESS;
	REG_TEST_T *array;
	mt_u32 array_width;
	mt_u32 reg_addr = REG_SYS_BLOCK_RESET;
	mt_u32 reg_val = 0;
	mt_u32 hd_venc_en = 0;

	//disable HD encoder
	ret_tmp = misc_reg_read32(reg_addr, &reg_val, 1);
	hd_venc_en = (1 << 31);
	reg_val &= ~(1 << 31);
	ret_tmp = misc_reg_write32(reg_addr, &reg_val, 1);

	//sw reset hdmi
	hdmi_block_reset_cmd();

	reg_val = (mt_u32)misc_reg_read8_single(HDMI20_REG_BASE_ADDR + 0xb7f);
	printf("reg[0x3b7f] = 0x%x\n", reg_val);
	reg_val = (mt_u32)misc_reg_read8_single(HDMI20_REG_BASE_ADDR + 0xc27);
	printf("reg[0x3c27] = 0x%x\n", reg_val);
	//Pwli module has been removed, 0x3c30 ~ 0x3c3c3c, 0x3c90 ~ 0x3c9c, 0x3cb0 ~ 0x3cbc can not be measured. Since pwli is closed, 0x3c26, 0x3c86, 0x3ca6 are fixed to 0
	//The vidgen module has been removed and 0x3e4c ~ 0x3e56 can not be measured. Since vidgen is closed, 0x3e3e is fixed to 0
	//0x3c68, 0x30f4, 0x30f8, 0x3065, 0x30d8-0x30eb, 0x3e24-0x3e38, 0x38cf

	//Verify default value
	//Do not embed the key ram, otherwise 0x304d~0x3051, 0x3636~0x363a is the embedded value.
	//The default values of bit3 and bit4 of 0x308f are not fixed, which are related to the reading time, and may also be 0.
	//The default values of bit7 and bit0 of 0x30f8 are not fixed, which is related to the reading time.
	array = g_hdmi_reg_rw_test;
	array_width = (mt_u32)(sizeof(g_hdmi_reg_rw_test) / sizeof(g_hdmi_reg_rw_test[0]));
	printf("Array_width[%d]\n", array_width);
	ret |= verify_reg_default_val(array, array_width, HDMI20_REG_BASE_ADDR);

	//write 0xff
	//printf("Array_width[%d]\n",array_width);
	ret |= verify_reg_wr_val(array, array_width, HDMI20_REG_BASE_ADDR, 0xff);

	//sw reset hdmi
	//hdmi_block_reset_cmd();

	//write 0x00
	//printf("Array_width[%d]\n",array_width);
	ret |= verify_reg_wr_val(array, array_width, HDMI20_REG_BASE_ADDR, 0x00);

	if ( hd_venc_en ) {
		ret_tmp = misc_reg_read32(reg_addr, &reg_val, 1);
		reg_val |= (1 << 31);
		ret_tmp = misc_reg_write32(reg_addr, &reg_val, 1);
	}

	//sw reset hdmi
	hdmi_block_reset_cmd();
	ret |= ret_tmp;
	#endif
	return (ret);
}

mt_u32 do_case_reg1xxx_rw(void)
{
	mt_u32 ret = BB_SUCCESS;
	#if defined(CONFIG_MT_CHIP_SYMPHONY6)
	REG_TEST_T *array;
	mt_u32 array_width;
	mt_u32 reg_addr = REG_SYS_BLOCK_RESET;
	mt_u32 reg_val = 0;
	mt_u32 hd_venc_en = 0;

	//disable HD encoder
	ret = misc_reg_read32(reg_addr, &reg_val, 1);
	hd_venc_en = (1 << 31);
	reg_val &= ~(1 << 31);
	ret = misc_reg_write32(reg_addr, &reg_val, 1);

	//sw reset hdmi
	hdmi_block_reset_cmd();

	//test reg 1xxx start
	array = g_hdmi_reg1xxx_rw_test;
	array_width = (mt_u32)(sizeof(g_hdmi_reg1xxx_rw_test) / sizeof(g_hdmi_reg1xxx_rw_test[0]));
	printf("Array_width[%d]\n", array_width);
	ret |= verify_reg1xxx_default_val(array, array_width, HDMI20_REG_BASE_ADDR);

	//write 0xff
	ret |= verify_reg1xxx_wr_val(array, array_width, HDMI20_REG_BASE_ADDR, 0xffffffff);

	//write 0x00
	ret |= verify_reg1xxx_wr_val(array, array_width, HDMI20_REG_BASE_ADDR, 0x00000000);

	if ( hd_venc_en ) {
		ret = misc_reg_read32(reg_addr, &reg_val, 1);
		reg_val |= (1 << 31);
		ret = misc_reg_write32(reg_addr, &reg_val, 1);
	}

	//sw reset hdmi
	hdmi_block_reset_cmd();
	#endif
	return ret;
}

