mt_u32 do_case_reg0xxx_rw_hangup_test(void)
{
	mt_u32 ret = BB_SUCCESS;
	#if defined(CONFIG_MT_CHIP_SYMPHONY6)
	REG_TEST_T *array;
	mt_u32 array_width;

	//Pwli module has been removed, 0x3c30 ~ 0x3c3c3c, 0x3c90 ~ 0x3c9c, 0x3cb0 ~ 0x3cbc can not be measured. Since pwli is closed, 0x3c26, 0x3c86, 0x3ca6 are fixed to 0
	//The vidgen module has been removed and 0x3e4c ~ 0x3e56 can not be measured. Since vidgen is closed, 0x3e3e is fixed to 0
	//0x3c68, 0x30f4, 0x30f8, 0x3065, 0x30d8-0x30eb, 0x3e24-0x3e38, 0x38cf

	//Verify default value
	//Do not embed the key ram, otherwise 0x304d~0x3051, 0x3636~0x363a is the embedded value.
	//The default values of bit3 and bit4 of 0x308f are not fixed, which are related to the reading time, and may also be 0.
	//The default values of bit7 and bit0 of 0x30f8 are not fixed, which is related to the reading time.
	array = g_hdmi_reg_rw_test;
	array_width = (mt_u32)(sizeof(g_hdmi_reg_rw_test) / sizeof(g_hdmi_reg_rw_test[0]));
	printf("Array_width[%d]\n", array_width);
	ret |= verify_reg_default_val(array, array_width, HDMI20_REG_BASE_ADDR);

	//write 0xff
	//printf("Array_width[%d]\n",array_width);
	ret |= verify_reg_wr_val_hangup_check(array, array_width, HDMI20_REG_BASE_ADDR, 0xff);

	//write 0x00
	//printf("Array_width[%d]\n",array_width);
	ret |= verify_reg_wr_val_hangup_check(array, array_width, HDMI20_REG_BASE_ADDR, 0x00);
	#endif
	return ret;
}

mt_u32 do_case_hdcp_key_ram_rw(mt_u32 *array, mt_u32 len, mt_u32 write)
{
	#if defined(CONFIG_MT_CHIP_SYMPHONY6)
	mt_u32 i = 0;
	bool_t ret = BB_SUCCESS;
	mt_u32 val;
	mt_u32 err_cnt1 = 0;

	if ( len > HDCP_SRAM_NUM) {
		SSHH_PRINTF("HDCP key len %d > max len %d", len, HDCP_SRAM_NUM);
		len = HDCP_SRAM_NUM;
		ret |= BB_FAILURE;
	}

	SSHH_PRINTF("HDCP key len=%d,w=%d\n", len, write);
	//SSHH_PRINTF("HDCP key array[0]=0x%08x\n",array[0]);
	ret |= ic_verify_reg_wt(REG_ADDR__READ_EN, 0x16885188UL); // read enable: HDCP_SRAM-->CPU
	ret |= ic_verify_reg_wt(REG_ADDR__HCLK_EN, 0x87654321UL); // Write enable: CPU-->HDCP_SRAM

	//SSHH_PRINTF("HDCP key w/r...\n");
	for (i = 0; i < ((len >> 2) + (len & 0x3)); i++) {
		if (write) {
			//SSHH_PRINTF("key[%03d]=0x%08x\n",i,array[i]);
			ret |= ic_verify_reg_wt(REG_ADDR__HDCP_KRAM_BASE + (i << 2), array[i]);
		} else {
			ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__HDCP_KRAM_BASE + (i << 2), array + i);
		}
	}

	if (write) {
		//SSHH_PRINTF("HDCP key w---->r...\n");
		for (i = 0; i < ((len >> 2) + (len & 0x3)); i++) {
			ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__HDCP_KRAM_BASE + (i << 2), &val);
			if (array[i] != val) {
				SSHH_PRINTF("\n Golden[%d]=0x%08x, cur=%08x\n", i, array[i], val);
				err_cnt1++;
			}
		}

		if (err_cnt1 == 0) {
			SSHH_PRINTF("\n Ap Cpu test write 0x%08x success!!!\n", array[0]);
		} else {
			SSHH_PRINTF("\n AP Cpu test write 0x%08x fail err1=%d!!!\n", array[0], (int)err_cnt1);
		}
	}
	#else
	bool_t ret = BB_SUCCESS;
	#endif
	return (mt_u32)ret;
}

mt_u32 do_case_hdcp_key_ram_rw_tee(mt_u32 *array, mt_u32 len, mt_u32 write)
{
	#if defined(CONFIG_MT_CHIP_SYMPHONY6)
	mt_u32 i = 0;
	bool_t ret = BB_SUCCESS;
	char cmd[100];

	memset(cmd, 0, sizeof(cmd));
	if ( len > HDCP_SRAM_NUM) {
		SSHH_PRINTF("HDCP key len %d > max len %d", len, HDCP_SRAM_NUM);
		len = HDCP_SRAM_NUM;
		ret |= BB_FAILURE;
	}

	SSHH_PRINTF("HDCP key len=%d,w=%d\n", len, write);
	//SSHH_PRINTF("HDCP key array[0]=0x%08x\n",array[0]);
	ret |= ic_verify_reg_wt(REG_ADDR__READ_EN, 0x16885188UL); // read enable: HDCP_SRAM-->CPU
	ret |= ic_verify_reg_wt(REG_ADDR__HCLK_EN, 0x87654321UL); // Write enable: CPU-->HDCP_SRAM

	//SSHH_PRINTF("HDCP key w/r...\n");
	if (write) {
		for (i = 0; i < ((len >> 2) + (len & 0x3)); i++) {
			//SSHH_PRINTF("key[%03d]=0x%08x\n",i,array[i]);
			sprintf(cmd, "optee_example_mt_firewall -c fw_host_io_write 0x%8lx 0x%8x\n", 0xbf130000UL + (i << 2), array[i]);
			system(cmd);
		}

		//SSHH_PRINTF("HDCP key w---->r...\n");
		sprintf(cmd, "optee_example_mt_firewall -c fw_host_io_read 0x%8lx 0x%x\n", 0xbf130000UL, len >> 2);
		system(cmd);
		SSHH_PRINTF("\n Check the value 0x%x with your big eyes ^-^!!!\n", array[0]);
	} else {
		sprintf(cmd, "optee_example_mt_firewall -c fw_host_io_read 0x%8lx 0x%x\n", 0xbf130000UL, len >> 2);
		system(cmd);
	}
	#else
	bool_t ret = BB_SUCCESS;
	#endif
	return (mt_u32)ret;
}

