mt_u32 do_case_hdcp_load_key(void)
{
	#if defined(CONFIG_MT_CHIP_SYMPHONY6)
	mt_u32 i = 0;
	mt_u32 data_w = 0;
	bool_t ret = BB_SUCCESS;
	mt_u32 p_key[HDCP_SRAM_NUM >> 2];
	char key;
	char key_tmp = 0;

	//check hdcp_keywr_lock[1:0] == 0x0
	ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__KEY_LOCK_CTRL, &data_w);
	if (data_w & (0x3 << 28)) {
		SSHH_PRINTF("hdcp_keywr_lock=0x%x is not ZERO, ap cpu can't operate key ram!!!", (data_w >> 28) & 0x3);
		ret |= BB_FAILURE;
	}

	do {
		SSHH_PRINTF("Pls type in a numer in 0~8, \n[0]: test write 0x00, [1]: test write 0xff [2]: read back to compare with [0]/[1]\n");
		SSHH_PRINTF("[3] ap cpu lock[1:0] test\n");
		SSHH_PRINTF("'a': key ram otp test\n");
		key_tmp = (char)_getch();
		if (key_tmp == 'a') {
			key = 7;
		} else {
			key = (char)(key_tmp - '0');
		}
	} while ((key < 0 || key > 8) && key_tmp != 'a');

	SSHH_PRINTF("You typed in %d...\n", (mt_u32)key);
	if (key & 0x1) {
		/* key ram can be r/w by any ram */
		/* Clear to all zeros test */
		SSHH_PRINTF("Start to test to write 0x00:%ld !!!\n", sizeof(p_key));
		memset((void *)p_key, 0, sizeof(p_key));
		ret |= do_case_hdcp_key_ram_rw(p_key, sizeof(p_key), 1);
	}

	if (key & 0x2) {
		/* Set 0xff to all test */
		SSHH_PRINTF("Start to test to write 0xff !!!\n");
		memset((void *)p_key, 0xffffffff, sizeof(p_key));
		ret |= do_case_hdcp_key_ram_rw(p_key, (mt_u32)(sizeof(p_key)), 1);
	}

	if (key & 0x4) {
		/* Write hdcp key test */
		SSHH_PRINTF("Start to test to write hdcp key !!!\n");
		ret |= do_case_hdcp_key_ram_rw(g_hdmi20_hdcp_key, sizeof(g_hdmi20_hdcp_key), 1);
	}

	if (key & 0x8) {
		mt_u32 data_w_tmp;
		mt_u32 mask = 0x1 << 28;
		SSHH_PRINTF("Start to test AP CPU can't write  hdcp_keywr_lock[0]=1!!!\n");
		ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__KEY_LOCK_CTRL, &data_w);
		data_w_tmp = data_w;
		ret |= (bool_t)ic_verify_reg_wt(REG_ADDR__KEY_LOCK_CTRL, data_w | mask);
		ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__KEY_LOCK_CTRL, &data_w);
		if (data_w_tmp & mask) {
			SSHH_PRINTF("AP CPU hdcp_keywr_lock[0] is NON-ZERO, can't do this test!!!\n");
			ret |= BB_FAILURE;
		} else if (data_w & mask) {
			SSHH_PRINTF("AP CPU hdcp_keywr_lock[0] test fail\n");
			ret |= BB_FAILURE;
		} else {
			SSHH_PRINTF("AP CPU hdcp_keywr_lock[0] test Success!!\n");
		}

		mask = 0x1 << 29;
		SSHH_PRINTF("Start to test AP CPU can't write  hdcp_keywr_lock[1]=1!!!\n");
		ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__KEY_LOCK_CTRL, &data_w);
		data_w_tmp = data_w;
		ret |= (bool_t)ic_verify_reg_wt(REG_ADDR__KEY_LOCK_CTRL, data_w | mask);
		ret |= (bool_t)ic_verify_reg_rd(REG_ADDR__KEY_LOCK_CTRL, &data_w);
		if (data_w_tmp & mask) {
			SSHH_PRINTF("AP CPU hdcp_keywr_lock[1] is NON-ZERO, can't do this test!!!\n");
			ret |= BB_FAILURE;
		} else if (data_w & mask) {
			SSHH_PRINTF("AP CPU hdcp_keywr_lock[1] test fail\n");
			ret |= BB_FAILURE;
		} else {
			SSHH_PRINTF("AP CPU hdcp_keywr_lock[1] test Success!!\n");
		}
	}

	if (key_tmp == 'a') {
		mt_u32 data_w_tmp = 0;
		SSHH_PRINTF("Start to test AP CPU otp r/w!!!\n");

		memset((void *)p_key, 0, sizeof(p_key));
		ret |= do_case_hdcp_key_ram_rw(p_key, (mt_u32)(sizeof(p_key)), 0);
		for (i = 0; i<HDCP_SRAM_NUM >> 2; i++) {
			data_w_tmp += p_key[i];
		}
		SSHH_PRINTF("Sum:0x%x\n", data_w_tmp);
		if (data_w_tmp == 0) {
			SSHH_PRINTF("Key ram is all zeros, pls wirte to non-zero\n");
			ret |= BB_FAILURE;
		}
		ret |= (bool_t)ic_verify_reg_wt(0xbf314400UL, 0x33250792);
		ret |= (bool_t)ic_verify_reg_wt(0xbf313da4UL, 0x20000000);
		ret |= (bool_t)ic_verify_reg_wt(0xbf314400UL, 0x33250792);
		ret |= (bool_t)ic_verify_reg_wt(0xbf313a78UL, 0x80000000);
		memset((void *)p_key, 0, sizeof(p_key));
		data_w_tmp = 0;
		ret |= do_case_hdcp_key_ram_rw(p_key, (mt_u32)(sizeof(p_key)), 0);
		for (i = 0; i<HDCP_SRAM_NUM >> 2; i++) {
			data_w_tmp += p_key[i];
		}
		SSHH_PRINTF("Sum1:0x%x\n", data_w_tmp);
		if (data_w_tmp != 0) {
			SSHH_PRINTF("Key ram read is non-zero after set otp\n");
			ret |= BB_FAILURE;
		}
	}

	if (ret == BB_SUCCESS) {
		SSHH_PRINTF("load hdcp key ok!!!\n");
	} else {
		SSHH_PRINTF("load hdcp key fail!!!\n");
	}
	#else
	bool_t ret = BB_SUCCESS;
	#endif
	return (mt_u32)ret;
}

