#if (defined(CONFIG_MT_CHIP_ETUDE2))
static mt_void hdmi_set_alanlog_clock(mt_u32 clk_tmds, mt_u32 clk_os_dig)
{
	mt_u32 reg_val = 0;
	mt_u32 reg_addr = 0;
	mt_u32 ret = BB_SUCCESS;
	mt_u32 clk_case = 0xff;

	if (594000 == clk_tmds && 594000 == clk_os_dig) {
		clk_case = 0;
	} else if (297000 == clk_tmds && 594000 == clk_os_dig) {
		clk_case = 1;
	} else if (297000 == clk_tmds && 297000 == clk_os_dig) {
		clk_case = 2;
	} else if (148500 == clk_tmds && 148500 == clk_os_dig) {
		clk_case = 3;
	} else if (74250 == clk_tmds && 74250 == clk_os_dig) {
		clk_case = 4;
	} else if (27000 == clk_tmds && 108000 == clk_os_dig) {
		clk_case = 5;
	}

	reg_addr = 0x1f5d0058;
	reg_val = 0x1CA983FA;
	if (5 == clk_case) {
		reg_val = 0x9C5883FA;
	}
	ret = misc_reg_write32(reg_addr, &reg_val, 1);

	reg_addr = 0x1f5d0060;
	switch (clk_case) {
		case 0:
			reg_val = 0x0;
			break;
		case 1:
		case 2:
			reg_val = 0x1;
			break;
		case 3:
			reg_val = 0x2;
			break;
		case 4:
			reg_val = 0x3;
			break;
		case 5:
			reg_val = 0x7;
			break;
		default:
			reg_val = 0x2;
			break;
	}
	ret = misc_reg_put32(reg_addr, 0x7 << 8, reg_val << 8);
	switch (clk_case) {
		case 0:
		case 1:
			reg_val = 0x3;
			break;
		case 2:
			reg_val = 0x2;
			break;
		case 3:
		case 5:
			reg_val = 0x1;
			break;
		case 4:
			reg_val = 0x0;
			break;
		default:
			reg_val = 0x1;
			break;
	}
	ret = misc_reg_put32(reg_addr, 0x3, reg_val);

	reg_addr = 0x1f5d009c;
	ret = misc_reg_put32(reg_addr, 0x7 << 19, 0x5 << 19);

	reg_addr = 0x1f157000;
	ret = misc_reg_put32(reg_addr, 0x1 << 7, 0x1 << 7);

	SiiLibTimeMicroDelay(1);

	reg_addr = 0x1f157000;
	ret = misc_reg_put32(reg_addr, 0x1 << 7, 0x0 << 7);

	reg_addr = 0x1f5d006c;
	switch (clk_case) {
		case 0:
			reg_val = 0x0030bbcb;
			break;
		case 1:
		case 2:
			reg_val = 0x0030bb0b;
			break;
		case 3:
		case 4:
		case 5:
			reg_val = 0x0030bb09;
			break;
		default:
			reg_val = 0x0030bb09;
			break;
	}
	ret = misc_reg_write32(reg_addr, &reg_val, 1);

	reg_addr = 0x1f5d0244;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);

	reg_addr = 0x1f5d0248;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);

	reg_addr = 0x1f5d024c;
	switch (clk_case) {
		case 0:
			reg_val = 0x08000078;
			break;
		case 1:
		case 2:
			reg_val = 0x08000038;
			break;
		case 3:
		case 4:
		case 5:
			reg_val = 0x08000008;
			break;
		default:
			reg_val = 0x08000008;
			break;
	}
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	if ( ret ) {
		return;
	}
}

static mt_void hdmi_alanlog_resistance_calibration(mt_u32 clk_tmds, mt_u32 clk_os_dig)
{
	//mt_u8 reg_val = 0;
	mt_u32 reg_addr = 0x1f5d024c;
	mt_u32 ret = BB_SUCCESS;

	ret = misc_reg_put32(reg_addr, 0x1 << 28, 0x0 << 28);
	ret = misc_reg_put32(reg_addr, 0x1 << 29, 0x0 << 29);
	SiiLibTimeMicroDelay(1);
	ret = misc_reg_put32(reg_addr, 0x1 << 29, 0x1 << 29);
	if ( ret ) {
		return;
	}
}

static mt_void hdmi_set_digital_clock(mt_u32 clk_tmds, mt_u32 clk_os_dig)
{
	mt_u32 reg_val = 0;
	mt_u32 reg_addr = 0;
	mt_u32 ret = BB_SUCCESS;
	mt_u32 clk_case = 0xff;

	if (594000 == clk_tmds && 594000 == clk_os_dig) {
		clk_case = 0;
	} else if (297000 == clk_tmds && 594000 == clk_os_dig) {
		clk_case = 1;
	} else if (297000 == clk_tmds && 297000 == clk_os_dig) {
		clk_case = 2;
	} else if (148500 == clk_tmds && 148500 == clk_os_dig) {
		clk_case = 3;
	} else if (74250 == clk_tmds && 74250 == clk_os_dig) {
		clk_case = 4;
	}
	/*else if(27000 == clk_tmds && 108000 == clk_os_dig)
		clk_case = 5;*/
	else {
		clk_case = 5;
	}

	reg_addr = 0x1f50a604;
	if (5 == clk_case) {
		reg_val = 0x5;
	} else {
		reg_val = 0;
	}
	ret = misc_reg_put32(reg_addr, 0x7 << 0, reg_val << 0);
	if (5 == clk_case) {
		reg_val = 0x5;
	} else if (1 == clk_case) {
		reg_val = 0x4;
	} else {
		reg_val = 0;
	}
	ret = misc_reg_put32(reg_addr, 0x7 << 3, reg_val << 3);
	ret = misc_reg_put32(reg_addr, 0x7 << 7, 0x0 << 7);
	if ( ret ) {
		return;
	}
}
#endif

static mt_void hdmi_set_kram(mt_u32 addr, mt_u32 val)
{
	#if defined (CONFIG_MT_CHIP_ETUDE2)
	//mt_u8 reg_val = 0;
	mt_u32 reg_addr = 0;
	mt_u32 ret = BB_SUCCESS;
	mt_u32 reg_val = 0;

	//step 4, set kram 0x1fe  to 0x00
	reg_addr = REG_ADDR__KRAM_W_CTRL;
	reg_val = 0x0;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	SiiLibTimeMicroDelay(1);
	reg_addr = REG_ADDR__KRAM_CTRL;
	//reg_val = 0x01fe1000;
	reg_val = 0x00001000;
	reg_val += ((addr & 0x1ff) << 16);//[24:16]
	reg_val += val & 0xff; //[7:0]
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	SiiLibTimeMicroDelay(1);
	reg_addr = REG_ADDR__KRAM_W_CTRL;
	reg_val = 0x0;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	SiiLibTimeMicroDelay(1);
	reg_addr = REG_ADDR__KRAM_W_CTRL;
	reg_val = 0x1;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	SiiLibTimeMicroDelay(1);
	reg_addr = REG_ADDR__KRAM_W_CTRL;
	reg_val = 0x0;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	SiiLibTimeMicroDelay(1);
	reg_addr = REG_ADDR__KRAM_CTRL;
	reg_val = 0x0;
	ret = misc_reg_write32(reg_addr, &reg_val, 1);
	SiiLibTimeMicroDelay(1);

	ret = misc_reg_put8(REG_ADDR__EPCM, 0xff, 0x20);
	if ( ret ) {
		return;
	}
	#endif
}

static mt_void hdmi_init(mt_u32 cs, mt_u32 first)
{
	mt_u32 ret = BB_SUCCESS;
	mt_u8 val[2];

	if (first) {
		ret = misc_reg_put8(REG_ADDR__AIP_HDMI2MHL, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__CLKPWD, 0xff, 0x04);
		ret = misc_reg_put8(REG_ADDR__PKT_FILTER_0, 0xff, 0x02);
		ret = misc_reg_put8(REG_ADDR__FUNC_SEL, 0xff, 0x01);
		ret = misc_reg_put8(REG_ADDR__ASRC, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__SYS_MISC, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__I2S_IN_MAP, 0xff, 0xe4);
		ret = misc_reg_put8(REG_ADDR__FREQ_SVAL, 0xff, 0x01);
		ret = misc_reg_put8(REG_ADDR__CLKRATIO, 0xff, 0x05);
		ret = misc_reg_put8(REG_ADDR__TEST_TXCTRL, 0xff, 0x02);
		ret = misc_reg_put8(REG_ADDR__N_SVAL1, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__TX_ZONEL_CTL4, 0xff, 0x04);
		ret = misc_reg_put8(REG_ADDR__N_SVAL2, 0xff, 0x10);
		ret = misc_reg_put8(REG_ADDR__SCRCTL, 0xff, 0x20);
		ret = misc_reg_put8(REG_ADDR__N_SVAL3, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__VP__INPUT_SYNC_ADJUST_CONFIG, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__CTS_TXSVAL1, 0xff, 0x93);
		ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC0__MULTI_CSC_CONFIG, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC0__MULTI_CSC_CONFIG + 1, 0xff, 0x08);
		ret = misc_reg_put8(REG_ADDR__CTS_TXSVAL2, 0xff, 0x69);
		ret = misc_reg_put8(REG_ADDR__CTS_TXSVAL3, 0xff, 0x00);
		//ret = misc_reg_put8(0x1f570da0, 0xff, 0x00);
		//ret = misc_reg_put8(0x1f570da1, 0xff, 0x08);
		ret = misc_reg_put8(REG_ADDR__I2S_CHST0, 0xff, 0x21);
		ret = misc_reg_put8(REG_ADDR__TXC_DATA_DIV, 0xff, 0x02);
		ret = misc_reg_put8(REG_ADDR__I2S_CHST1, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__I2S_CHST2, 0xff, 0xa0);
		ret = misc_reg_put8(REG_ADDR__MHL_DP_CTL1, 0xff, 0xa7);
		ret = misc_reg_put8(REG_ADDR__AIP_IN_AUD_ID, 0xff, 0x01);
		//ret = misc_reg_put8(0x1f570da0, 0xff, 0x21);
		//ret = misc_reg_put8(0x1f570da1, 0xff, 0x08);
		ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_MULTCOEFFR1C1, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_MULTCOEFFR1C1 + 1, 0xff, 0x10);
		#if defined(CONFIG_MT_CHIP_ETUDE2)
		ret = misc_reg_put8(REG_ADDR__BYTE_RW_MODE, 0xff, 0x01);
		#endif
		ret = misc_reg_put8(REG_ADDR__DIPT_CNTL, 0xff, 0x06);
		//ret = misc_reg_put8(0x1f570066, 0xff, 0x80);
		ret = misc_reg_put8(REG_ADDR__MHL_TOP_CTL, 0xff, 0x90);
		ret = misc_reg_put8(REG_ADDR__MHL_DP_CTL0, 0xff, 0x10);
		ret = misc_reg_put8(REG_ADDR__AIP_RST, 0xff, 0x03);
		ret = misc_reg_put8(REG_ADDR__I2S_CHST3, 0xff, 0x02);
		//ret = misc_reg_put8(REG_ADDR__I2S_CHST4, 0xff, 0x0b);
		ret = misc_reg_put8(REG_ADDR__I2S_CHST4, 0xff, 0x02);
		ret = misc_reg_put8(REG_ADDR__ACR_CTRL, 0xff, 0x0e);
		//ret = misc_reg_put8(REG_ADDR__I2S_IN_SIZE, 0xff, 0x0b);
		ret = misc_reg_put8(REG_ADDR__I2S_IN_SIZE, 0xff, 0x02);
		ret = misc_reg_put8(REG_ADDR__I2S_IN_CTRL, 0xff, 0x60);
		ret = misc_reg_put8(REG_ADDR__AUD_MODE, 0xff, 0x10);
		ret = misc_reg_put8(REG_ADDR__AUDP_TXCTRL, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__AUD_EN, 0xff, 0x03);
		ret = misc_reg_put8(REG_ADDR__TPI_DOWN_SMPL_CTRL, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__TPI_AUD_CONFIG, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__TPI_AUD_FS, 0xff, 0x02);
		ret = misc_reg_put8(REG_ADDR__AIP_RST, 0xff, 0x00);
		ret = misc_reg_put8(REG_ADDR__INT_MUX, 0xff, 0x02);
	}
	switch (cs) { //8bit
		case 0:
			//RGB
			val[0] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG, 0x21);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1, val[1] & 0xfc);
			ret = misc_reg_write8_single(REG_ADDR__VP__OUTPUT_FORMAT, 0x00);
			ret = misc_reg_write8_single(REG_ADDR__VP__OUTPUT_FORMAT + 1, 0x00);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__C444_C422_CONFIG, 0x00);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__C422_C420_CONFIG, 0x02);
			break;
		case 1:
			//YUV422
			val[0] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG, 0x00);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1, val[1] & 0xfc);
			val[0] = misc_reg_read8_single(REG_ADDR__VP__OUTPUT_FORMAT);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__OUTPUT_FORMAT + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__OUTPUT_FORMAT, val[0]);
			ret = misc_reg_put8(REG_ADDR__VP__OUTPUT_FORMAT + 1, 1 << 2, 0 << 2);
			ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__C444_C422_CONFIG, 1, 1);
			ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__C422_C420_CONFIG, 1, 0);
			break;
		case 2:
			//YUV444
			val[0] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG, 0x00);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1, val[1] & 0xfc);
			val[0] = misc_reg_read8_single(REG_ADDR__VP__OUTPUT_FORMAT);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__OUTPUT_FORMAT + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__OUTPUT_FORMAT, val[0]);
			ret = misc_reg_put8(REG_ADDR__VP__OUTPUT_FORMAT + 1, 1 << 2, 0 << 2);
			ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__C444_C422_CONFIG, 1, 0);
			ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__C422_C420_CONFIG, 1, 0);
			break;
		case 3:
			//YUV420
			val[0] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG, 0x00);
			ret = misc_reg_write8_single(REG_ADDR__VP__CMS__CSC1__MULTI_CSC_CONFIG + 1, val[1] & 0xfc);
			val[0] = misc_reg_read8_single(REG_ADDR__VP__OUTPUT_FORMAT);
			val[1] = misc_reg_read8_single(REG_ADDR__VP__OUTPUT_FORMAT + 1);
			ret = misc_reg_write8_single(REG_ADDR__VP__OUTPUT_FORMAT, val[0]);
			ret = misc_reg_put8(REG_ADDR__VP__OUTPUT_FORMAT + 1, 1 << 2, 1 << 2);
			ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__C444_C422_CONFIG, 1, 1);
			ret = misc_reg_put8(REG_ADDR__VP__CMS__CSC1__C422_C420_CONFIG, 0x3, 1);
			break;
		default:
			break;
	}
	if ( ret ) {
		return;
	}
}

static mt_void hdmi_send_info(mt_u32 info_type, info_struct_t info)
{
	mt_u32 ret = BB_SUCCESS;
	mt_u32 i;

	ret = misc_reg_put8(REG_ADDR__TPI_INFO_FSEL, 0xff, (mt_u8)info_type);
	ret = misc_reg_put8(REG_ADDR__TPI_INFO_B0, 0xff, info.type);
	ret = misc_reg_put8(REG_ADDR__TPI_INFO_B1, 0xff, info.version);
	ret = misc_reg_put8(REG_ADDR__TPI_INFO_B2, 0xff, info.length);
	for (i = 0; i < info.length + 1; i++) {
		ret = misc_reg_put8(REG_ADDR__TPI_INFO_B3 + i, 0xff, info.pb_byte[i]);
	}
	ret = misc_reg_put8(REG_ADDR__TPI_INFO_EN, 0xff, 0xc0);
	if ( ret ) {
		return;
	}
}

